/* Shared browser-local state. No backend calls or production authentication. */
window.Abibi=(()=>{'use strict';const D=window.ABIBI_DATA,KEY='abibi-ui-v3';let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(!state||state.version!==3)state={version:3,branch:null,cart:[],favorites:[],profile:{name:'مهمان آبی‌بی',phone:'',email:'',birthday:''},addresses:[],orders:[],points:D.club.initialPoints,qualifying:D.club.initialQualifying,ledger:[{id:'welcome',label:'اعتبار اولیه نمایشی باشگاه',amount:1250,date:'2026-10-13T08:00:00Z'}],coupons:[]};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],fa=n=>Number(n).toLocaleString('fa-IR'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),digits=s=>String(s).replace(/[۰-۹]/g,x=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(x)).replace(/[٠-٩]/g,x=>'٠١٢٣٤٥٦٧٨٩'.indexOf(x)),money=n=>`<span class="price">${fa(n)}<small>تومان</small></span>`,product=id=>D.products.find(p=>p.id===Number(id)),count=()=>state.cart.reduce((a,x)=>a+x.qty,0),unit=p=>p.salePrice??p.price,sum=()=>state.cart.reduce((a,x)=>a+(unit(product(x.id))+x.extra)*x.qty,0),subtotal=()=>state.cart.reduce((a,x)=>a+(product(x.id).price+x.extra)*x.qty,0),id=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),date=d=>new Date(d).toLocaleDateString('fa-IR'),tier=()=>{const tiers=D.club.tiers;let index=tiers.reduce((a,t,i)=>state.qualifying>=t.min?i:a,0);const current=tiers[index],next=tiers[index+1],remaining=next?Math.max(0,next.min-state.qualifying):0,percent=next?Math.min(100,Math.max(0,(state.qualifying-current.min)/(next.min-current.min)*100)):100;return{current,next,remaining,percent}};
function toast(text){const el=$('#noticeToast');if(!el)return;el.querySelector('.toast-body').textContent=text;bootstrap.Toast.getOrCreateInstance(el,{delay:2800}).show()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('ذخیره‌سازی مرورگر در دسترس نیست؛ تغییرات فقط تا بستن صفحه باقی می‌مانند.')}sync();document.dispatchEvent(new Event('abibi:change'))}
function sync(){$$('[data-cart-count]').forEach(el=>el.textContent=fa(count()));$$('[data-profile-name]').forEach(el=>el.textContent=state.profile.name);$$('[data-branch-label]').forEach(el=>el.textContent=D.branches.find(b=>b.id===state.branch)?.name||'انتخاب شعبه');$$('[data-points]').forEach(el=>el.textContent=fa(state.points));$$('[data-member-tier]').forEach(el=>el.textContent=tier().current.name);const current=location.pathname.split('/').pop()||'index.html';$$('nav a').forEach(a=>{if(a.getAttribute('href')===current){a.classList.add('active');a.setAttribute('aria-current','page')}});const mini=$('.member-mini small');if(mini)mini.textContent='حساب نمایشی · عضو '+tier().current.name;$$('[data-cart-nav]').forEach(el=>el.setAttribute('aria-label','سبد خرید، '+fa(count())+' مورد'));const currentPage=document.body.dataset.page;const accountPages=['dashboard','profile','addresses','orders','order-detail','favorites','login'];const clubPages=['club','levels','points','rewards','coupons'];const key=accountPages.includes(currentPage)?'dashboard':clubPages.includes(currentPage)?'club':['checkout','success'].includes(currentPage)?'cart':currentPage==='product'?'menu':currentPage;$$('.bottom-nav a').forEach(el=>{const active=el.getAttribute('href')===key+'.html';el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')})}
function add(productId,extra=0,note=''){if(!state.branch){sessionStorage.setItem('abibi-return',location.pathname.split('/').pop()+location.search);location.href='branches.html';return}const p=product(productId);if(!p)return;let line=state.cart.find(x=>x.id===p.id&&x.extra===extra&&x.note===note);if(line){if(line.qty>=20){toast('حداکثر تعداد هر مورد ۲۰ است');return}line.qty++}else state.cart.push({key:id(),id:p.id,qty:1,extra,note});save();toast('به سبد خوشمزه‌هات اضافه شد')}
function quantity(key,delta){const x=state.cart.find(x=>x.key===key);if(!x)return;x.qty=Math.min(20,x.qty+delta);state.cart=state.cart.filter(x=>x.qty>0);save()}
function pricing(p){return p.salePrice?`<span class="price-stack"><del aria-label="قیمت قبل از تخفیف">${fa(p.price)}</del>${money(unit(p))}</span>`:money(p.price)}
function discount(p){return p.salePrice?Math.round((1-p.salePrice/p.price)*100):0}
function card(p,{special=false,col='col-6 col-xl-3'}={}){return `<div class="${col}"><article class="food-card">${p.salePrice?`<span class="discount-badge">${fa(discount(p))}٪ تخفیف</span>`:special?'<span class="food-tag">پیشنهاد آبی‌بی</span>':''}<button type="button" class="fav-btn ${state.favorites.includes(p.id)?'selected':''}" data-favorite="${p.id}" aria-pressed="${state.favorites.includes(p.id)}" aria-label="علاقه‌مندی ${p.name}">${state.favorites.includes(p.id)?'♥':'♡'}</button><a href="product.html?id=${p.id}"><img class="food-image" src="assets/image/${p.img}" alt="${p.name}" loading="lazy"></a><div class="card-body"><h3><a href="product.html?id=${p.id}">${p.name}</a></h3><p>${p.desc}</p><div class="d-flex justify-content-between align-items-center gap-1">${pricing(p)}<button type="button" class="add-btn" data-add="${p.id}" aria-label="افزودن ${p.name}">+</button></div></div></article></div>`}
function summary(mode){const shipping=mode==='delivery'?35000:0,saving=subtotal()-sum();return `<div class="summary-line"><span>جمع غذاها (${fa(count())} مورد)</span>${money(subtotal())}</div>${saving?`<div class="summary-line discount-line"><span>سود شما از تخفیف</span><span>− ${money(saving)}</span></div>`:''}${mode?`<div class="summary-line"><span>${mode==='delivery'?'ارسال (نمونه)':'تحویل حضوری'}</span>${money(shipping)}</div>`:''}<div class="summary-line total"><strong>جمع ${mode?'نهایی':'غذاها'}</strong>${money(sum()+shipping)}</div>`}

const empty=(title,text,href='menu.html',label='مشاهده منو')=>`<div class="empty-state"><strong>${title}</strong><p>${text}</p>${href?`<a class="btn btn-primary mt-2" href="${href}">${label}</a>`:''}</div>`;
document.addEventListener('click',e=>{const addBtn=e.target.closest('[data-add]');if(addBtn)add(addBtn.dataset.add);const fav=e.target.closest('[data-favorite]');if(fav){const pid=Number(fav.dataset.favorite);state.favorites=state.favorites.includes(pid)?state.favorites.filter(x=>x!==pid):[...state.favorites,pid];save()}const q=e.target.closest('[data-qty]');if(q)quantity(q.dataset.key,Number(q.dataset.qty));const rm=e.target.closest('[data-remove]');if(rm){state.cart=state.cart.filter(x=>x.key!==rm.dataset.remove);save()}});sync();return {D,state,$,$$,fa,esc,digits,money,product,unit,pricing,discount,count,sum,subtotal,id,date,tier,toast,save,sync,add,quantity,card,summary,empty};})();
